import{_ as i,l,o as e,c as n,v as t,p as s,x as r,d,i as h,S as c}from"./chunks/framework.InCnrqk-.js";const A=JSON.parse('{"title":"基数与桶","description":"","frontmatter":{"title":"基数与桶","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/radix-bucket.md","filePath":"cs/radix-bucket.md","lastUpdated":1789023840000}'),p={name:"cs/radix-bucket.md"};function D(S,a,E,u,_,B){const o=l("Mermaid");return e(),n("div",null,[a[1]||(a[1]=t('<h1 id="基数与桶" tabindex="-1">基数与桶 <a class="header-anchor" href="#基数与桶" aria-label="Permalink to &quot;基数与桶&quot;">​</a></h1><div class="epigraph"><p>LSD 基数依赖稳定的按位分配；桶排序把均匀假设换成期望线性，最坏仍可退回比较。</p><footer>—— 据 Knuth, TAOCP vol. 3；CLRS 第 8 章整理</footer></div><p>上一课<a href="/cs/linear-time-sort">线性时间排序</a>已交出计数与 LSD 基数：键在 \\(\\{0,\\ldots,k\\}\\) 或 \\(d\\) 位数字上，\\(\\Theta(n+k)\\) 或 \\(\\Theta(d(n+r))\\)。主干停在「从低位到高位、子过程必须稳定」。本课不重写前缀和。缺口是两块对照：桶排序的概率模型，以及 MSD 与字符串——上一课点名未写。后课选择第 \\(k\\) 小仍回比较模型。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>计数要值域数组。若键是 \\([0,1)\\) 上的实数（或已归一化），不能直接当索引。桶排序：划 \\(n\\) 个等宽桶，落入同一桶的用插入排，再拼接。均匀独立时每桶期望 \\(O(1)\\) 个，总期望 \\(\\Theta(n)\\)；最坏一桶装完，\\(O(n^2)\\)。缺口不是再推翻比较下界，而是<strong>期望线性买分布假设</strong>，与计数的最坏线性分开。</p><p>MSD 基数：先按最高位分桶，再对每个非空桶递归。对变长字符串自然：已分叉的前缀不必再比。LSD 要定长或先按长度垫。稳定：LSD 必须；MSD 分桶后各桶独立，桶内可用插入或再 MSD。</p><h3 id="桶不是散列" tabindex="-1">桶不是散列 <a class="header-anchor" href="#桶不是散列" aria-label="Permalink to &quot;桶不是散列&quot;">​</a></h3><p>散列打散且不保序。桶的编号是键的单调函数，拼接才有序。把哈希表当排序是另一错误模型。计数是桶的极端：每个键值一个桶，桶内至多计数、没有比较。</p><p><span class="marginnote">Knuth 把分配排序与比较排序分卷叙述。CLRS 8.4 桶排序、8.3 基数。本课把上一课未写的均匀假设与 MSD 收进来，不把浮点位型再映射一遍。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>桶：算桶号 \\(\\lfloor n\\cdot key\\rfloor\\)（键已在 \\([0,1)\\)），桶内插入，按桶号扫出。LSD：对 \\(j=1..d\\) 稳定计数按第 \\(j\\) 位。MSD：按最高位分配，对大小超过阈值的桶递归，小桶改插入。</p>',11)),(e(),s(c,null,{default:r(()=>[h(o,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20INT%5B%22%E6%95%B4%E6%95%B0%20%2F%20%E5%AE%9A%E9%95%BF%E6%95%B0%E5%AD%97%22%5D%20--%3E%20LSD%5B%22LSD%EF%BC%9A%E7%A8%B3%E5%AE%9A%E6%8C%89%E4%BD%8D%22%5D%0A%20%20REAL%5B%22%E5%9D%87%E5%8C%80%20%5B0%2C1)%22%5D%20--%3E%20BUCK%5B%22%E6%A1%B6%20%2B%20%E6%A1%B6%E5%86%85%E6%8F%92%E5%85%A5%22%5D%0A%20%20STR%5B%22%E5%8F%98%E9%95%BF%E4%B8%B2%22%5D%20--%3E%20MSD%5B%22MSD%EF%BC%9A%E5%89%8D%E7%BC%80%E5%88%86%E5%8F%89%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>正确性：LSD 归纳「最低 \\(j\\) 位有序」；MSD 归纳「当前前缀已对齐，桶间有序」。桶的期望对输入分布，不是算法抛硬币。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>空间：桶指针加计数数组。缓存：大量随机桶号会打散写，实践上不如比较排序友好——本课点名，不模拟 Cache。与<a href="/cs/quicksort-3way">三路快排</a>：MSD 的「当前位相等」进入同一子桶，语义相近，模型仍是数字位而非比较。</p><p>\\(k\\) 或 \\(r\\) 随 \\(n\\) 增长时，线性系数变差。单词长 RAM 上的整数排序更快，仍不启用。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不声称一般排序 \\(O(n)\\)。没有值域或分布，比较墙仍在。外存多路归并不是桶。后课默认：LSD/MSD 与桶的假设已分开；第 \\(k\\) 小回到比较模型，不必排完。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>LSD 要稳定按位；MSD 适合变长前缀。</li><li>桶排序期望线性依赖均匀；最坏平方。</li><li>选择第 \\(k\\) 小不是全排序，下一课另开。</li><li>出处：Knuth, TAOCP vol. 3；CLRS 第 8 章。</li></ul>',8))])}const f=i(p,[["render",D]]);export{A as __pageData,f as default};
